// Original Mallside still illustrations; no film footage, logos or external artwork.
export const cinemaPalette=id=>id==='note'?['#c08c6b','#ead9ae','#48665c']:id==='lost'?['#688491','#ded9c4','#77584c']:['#607f89','#ddd6b6','#b87c61'];
export function cinemaArtSVG(id,scene=0){const [sky,paper,accent]=cinemaPalette(id),people=`<g fill="${accent}"><circle cx="${scene===0?140:125}" cy="100" r="10"/><path d="M${scene===0?140:125} 112v40m-15-23 15-17 15 17m-15 23-12 24m12-24 12 24" fill="none" stroke="${accent}" stroke-width="7" stroke-linecap="round"/>${scene>0?'<circle cx="220" cy="100" r="10"/><path d="M220 112v40m-15-23 15-17 15 17m-15 23-12 24m12-24 12 24" fill="none" stroke="'+accent+'" stroke-width="7" stroke-linecap="round"/>':''}</g>`;const prop=id==='umbrella'?`<g><path d="M92 81q68-91 136 0Z" fill="${paper}"/><path d="M160 80v52q0 20 17 10" fill="none" stroke="${paper}" stroke-width="4"/>${scene===0?Array.from({length:7},(_,i)=>`<path d="M${35+i*46} 22l-6 15m6 16-6 15" stroke="${paper}" stroke-width="2"/>`).join(''):''}</g>`:id==='note'?`<path d="M181 151V90m0 24-18-12m18 25 20-14" stroke="#536d50" stroke-width="5"/><g fill="#d7aa54">${[0,1,2,3,4,5].map(i=>`<ellipse cx="${181+Math.sin(i*Math.PI/3)*12}" cy="${85+Math.cos(i*Math.PI/3)*12}" rx="6" ry="11" transform="rotate(${-i*60} ${181+Math.sin(i*Math.PI/3)*12} ${85+Math.cos(i*Math.PI/3)*12})"/>`).join('')}</g><circle cx="181" cy="85" r="8" fill="#795e42"/><path d="M165 150h32l-4 27h-24Z" fill="${paper}"/>`:`<path d="M155 122h48l-4 45h-40Z" fill="${paper}"/><path d="M168 125v-9q11-22 22 0v9" fill="none" stroke="${paper}" stroke-width="5"/><path d="M83 173h194m-170 0v15m146-15v15" stroke="${accent}" stroke-width="6"/>`;return `<svg viewBox="0 0 360 210" class="cinema-art" role="img" aria-label="Original illustrated still for this Mallside short"><rect width="360" height="210" rx="10" fill="${sky}"/><circle cx="294" cy="39" r="20" fill="${paper}"/><path d="M0 159Q90 136 180 160T360 159V210H0Z" fill="${paper}" opacity=".2"/>${people}${prop}<path d="M0 194H360" stroke="${paper}" stroke-width="2"/></svg>`;}
export function paintCinemaArt(c,id,scene,width,height){const [sky,paper,accent]=cinemaPalette(id);c.save();c.scale(width/360,height/210);c.fillStyle=sky;c.fillRect(0,0,360,210);c.fillStyle=paper;c.beginPath();c.arc(294,39,20,0,Math.PI*2);c.fill();c.globalAlpha=.2;c.fillRect(0,159,360,51);c.globalAlpha=1;c.lineCap='round';for(const x of scene>0?[125,220]:[140]){c.fillStyle=accent;c.beginPath();c.arc(x,100,10,0,Math.PI*2);c.fill();c.strokeStyle=accent;c.lineWidth=7;c.beginPath();c.moveTo(x,112);c.lineTo(x,152);c.moveTo(x-15,129);c.lineTo(x,112);c.lineTo(x+15,129);c.moveTo(x-12,176);c.lineTo(x,152);c.lineTo(x+12,176);c.stroke();}c.fillStyle=paper;c.strokeStyle=paper;c.lineWidth=4;
 if(id==='umbrella'){c.beginPath();c.moveTo(92,81);c.quadraticCurveTo(160,-10,228,81);c.closePath();c.fill();c.beginPath();c.moveTo(160,80);c.lineTo(160,132);c.quadraticCurveTo(160,152,177,142);c.stroke();if(!scene){c.lineWidth=2;for(let i=0;i<7;i++){c.beginPath();c.moveTo(35+i*46,22);c.lineTo(29+i*46,37);c.moveTo(35+i*46,53);c.lineTo(29+i*46,68);c.stroke();}}}
 else if(id==='note'){c.strokeStyle='#536d50';c.lineWidth=5;c.beginPath();c.moveTo(181,151);c.lineTo(181,90);c.stroke();c.fillStyle='#d7aa54';for(let i=0;i<6;i++){c.beginPath();c.ellipse(181+Math.sin(i*Math.PI/3)*12,85+Math.cos(i*Math.PI/3)*12,6,11,-i*Math.PI/3,0,Math.PI*2);c.fill();}c.fillStyle='#795e42';c.beginPath();c.arc(181,85,8,0,Math.PI*2);c.fill();c.fillStyle=paper;c.fillRect(165,150,32,27);}
 else{c.fillRect(155,122,48,45);c.beginPath();c.moveTo(168,125);c.lineTo(168,116);c.quadraticCurveTo(179,94,190,116);c.lineTo(190,125);c.stroke();c.strokeStyle=accent;c.lineWidth=6;c.beginPath();c.moveTo(83,173);c.lineTo(277,173);c.moveTo(107,173);c.lineTo(107,188);c.moveTo(253,173);c.lineTo(253,188);c.stroke();}c.restore();}
